const stepAttemptObservation = `-- name: StepAttemptObservation :one
SELECT r.id AS run_id, r.project_id, r.status,
 (s.attempt=$1 AND s.status=$2)::boolean AS live_attempt,
 COALESCE(o.actor,'run/' || r.id::text)::text AS owner,
 o.actor_principal AS owner_principal
FROM steps s JOIN runs r ON r.id=s.run_id LEFT JOIN run_inference_owners o ON o.run_id=r.id
WHERE s.id=$3
`

type StepAttemptObservationParams struct {
	Attempt          int64
	RunningStepState string
	StepID           ids.ID
}

type StepAttemptObservationRow struct {
	RunID          ids.ID
	ProjectID      ids.ID
	Status         string
	LiveAttempt    bool
	Owner          string
	OwnerPrincipal ids.ID
}

// A step attempt's runtime credential names only the step and attempt. Its
// run, project, liveness and billing owner are read in one snapshot.
func (q *Queries) StepAttemptObservation(ctx context.Context, arg StepAttemptObservationParams) (StepAttemptObservationRow, error) {
	row := q.db.QueryRowContext(ctx, stepAttemptObservation, arg.Attempt, arg.RunningStepState, arg.StepID)
	var i StepAttemptObservationRow
	err := row.Scan(
		&i.RunID,
		&i.ProjectID,
		&i.Status,
		&i.LiveAttempt,
		&i.Owner,
		&i.OwnerPrincipal,
	)
	return i, err
}

